sections.css:
.debossed-volume{background: linear-gradient(145deg, var(--surface-top), var(--surface-bottom)); backdrop-filter: blur(60px) saturate(140%); border-radius: 2rem; box-shadow: inset 2px 2px 4px var(--shadow-light),
    inset -2px -2px 8px var(--shadow-dark),
    10px 20px 40px rgba(0,0,0,0.05); position: relative; isolation: isolate; border: 1px solid rgba(255, 255, 255, 0.1); transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.6s;}
.debossed-volume::before{content: ""; position: absolute; inset: 0px; border-radius: inherit; background: radial-gradient(
    600px circle at var(--mouse-x) var(--mouse-y),
    var(--atmos-cyan),
    transparent 50%
  ); opacity: 0; mix-blend-mode: overlay; transition: opacity 0.4s; pointer-events: none; z-index: -1;}
.debossed-volume:hover{transform: translateY(-4px) scale(1.01); box-shadow: inset 2px 2px 6px var(--shadow-light),
    inset -2px -2px 10px var(--shadow-dark),
    15px 30px 60px rgba(0,0,0,0.08);}
.debossed-volume:hover::before{opacity: 0.15;}
.parallax-card{}
.data-node{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; font-weight: 500; letter-spacing: -0.05em;}
h2, h3{font-size: inherit; font-weight: inherit;}
h2, h3, p{margin: 0px;}
.absolute{position: absolute;}
.relative{position: relative;}
.-right-20{right: -5rem;}
.-top-20{top: -5rem;}
.z-10{z-index: 10;}
.mb-2{margin-bottom: 0.5rem;}
.mb-20{margin-bottom: 5rem;}
.mb-4{margin-bottom: 1rem;}
.mt-12{margin-top: 3rem;}
.mt-16{margin-top: 4rem;}
.mt-6{margin-top: 1.5rem;}
.flex{display: flex;}
.grid{display: grid;}
.h-1{height: 0.25rem;}
.h-2{height: 0.5rem;}
.h-96{height: 24rem;}
.h-full{height: 100%;}
.min-h-\[400px\]{min-height: 400px;}
.w-2{width: 0.5rem;}
.w-96{width: 24rem;}
.w-\[99\.9\%\]{width: 99.9%;}
.w-full{width: 100%;}
.max-w-md{max-width: 28rem;}
.auto-rows-auto{grid-auto-rows: auto;}
.grid-cols-1{grid-template-columns: repeat(1, minmax(0px, 1fr));}
.flex-col{flex-direction: column;}
.items-start{align-items: flex-start;}
.items-center{align-items: center;}
.items-baseline{align-items: baseline;}
.justify-between{justify-content: space-between;}
.gap-2{gap: 0.5rem;}
.gap-6{gap: 1.5rem;}
.overflow-hidden{overflow: hidden;}
.rounded-full{border-radius: 9999px;}
.bg-\[var\(--alert-orange\)\]{background-color: var(--alert-orange);}
.bg-\[var\(--atmos-cyan\)\]{background-color: var(--atmos-cyan);}
.bg-\[var\(--shadow-dark\)\]{background-color: var(--shadow-dark);}
.p-10{padding: 2.5rem;}
.text-2xl{font-size: 1.5rem; line-height: 2rem;}
.text-4xl{font-size: 2.25rem; line-height: 2.5rem;}
.text-7xl{font-size: 4.5rem; line-height: 1;}
.text-lg{font-size: 1.125rem; line-height: 1.75rem;}
.text-xs{font-size: 0.75rem; line-height: 1rem;}
.font-light{font-weight: 300;}
.font-medium{font-weight: 500;}
.uppercase{text-transform: uppercase;}
.leading-\[1\.1\]{line-height: 1.1;}
.leading-relaxed{line-height: 1.625;}
.tracking-tight{letter-spacing: -0.025em;}
.tracking-tighter{letter-spacing: -0.05em;}
.tracking-widest{letter-spacing: 0.1em;}
.text-\[var\(--alert-orange\)\]{color: var(--alert-orange);}
.text-\[var\(--text-core\)\]{color: var(--text-core);}
.text-\[var\(--text-dim\)\]{color: var(--text-dim);}
.opacity-10{opacity: 0.1;}
.mix-blend-overlay{mix-blend-mode: overlay;}
.shadow-\[0_0_10px_var\(--alert-orange\)\]{--tw-shadow: 0 0 10px var(--alert-orange); --tw-shadow-colored: 0 0 10px var(--tw-shadow-color); box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);}
.shadow-\[0_0_12px_var\(--atmos-cyan\)\]{--tw-shadow: 0 0 12px var(--atmos-cyan); --tw-shadow-colored: 0 0 12px var(--tw-shadow-color); box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);}
.blur-\[100px\]{--tw-blur: blur(100px); filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.filter{filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow);}
.transition-opacity{transition-property: opacity; transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1); transition-duration: 150ms;}
.duration-700{transition-duration: 700ms;}
.group:hover .group-hover\:opacity-30{opacity: 0.3;}
@media (min-width: 768px){.md\:p-14{padding: 3.5rem;}}
@media (min-width: 768px){.md\:text-5xl{font-size: 3rem; line-height: 1;}}
